//! Tauri bridge for the Musiverion desktop app.
//!
//! This crate only adapts `mv-app` to Tauri commands. It holds no business
//! logic. TypeScript bindings for every command are generated by
//! `tauri-specta` into `apps/desktop/src/bindings.ts` on debug builds.

use tauri_specta::{Builder, collect_commands};

/// Where debug builds write the generated TypeScript bindings.
const BINDINGS_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../src/bindings.ts");

/// Health check: returns the application service's ping reply.
#[tauri::command]
#[specta::specta]
fn ping() -> mv_app::PingReply {
    mv_app::ping()
}

fn specta_builder() -> Builder<tauri::Wry> {
    Builder::<tauri::Wry>::new().commands(collect_commands![ping])
}

fn typescript() -> specta_typescript::Typescript {
    specta_typescript::Typescript::default()
}

/// Starts the desktop app.
pub fn run() {
    let builder = specta_builder();

    #[cfg(debug_assertions)]
    if let Err(err) = builder.export(typescript(), BINDINGS_PATH) {
        eprintln!("failed to export TypeScript bindings: {err}");
    }

    let result = tauri::Builder::default()
        .invoke_handler(builder.invoke_handler())
        .setup(move |app| {
            builder.mount_events(app);
            Ok(())
        })
        .run(tauri::generate_context!());

    if let Err(err) = result {
        eprintln!("error while running Musiverion: {err}");
        std::process::exit(1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Fails when `src/bindings.ts` is stale. Run the app once in debug
    /// (`just dev`) or set `UPDATE_BINDINGS=1` to regenerate it.
    #[test]
    fn bindings_are_up_to_date() {
        if std::env::var_os("UPDATE_BINDINGS").is_some() {
            specta_builder()
                .export(typescript(), BINDINGS_PATH)
                .unwrap();
        }
        let tmp = std::env::temp_dir().join("musiverion-bindings-check.ts");
        specta_builder().export(typescript(), &tmp).unwrap();
        let fresh = std::fs::read_to_string(&tmp).unwrap();
        let committed = std::fs::read_to_string(BINDINGS_PATH).unwrap();
        assert_eq!(
            fresh.replace("\r\n", "\n"),
            committed.replace("\r\n", "\n"),
            "bindings.ts is stale"
        );
    }
}
